
























import Vue from 'vue';
import Component from 'vue-class-component';
import { Tab as TabType } from '@/store/modules/tabs';
import Tab from '@/components/ui/Tab.vue';
import IconPlus from '@/assets/icons/plus.svg';
import { Mutation, State } from 'vuex-class';
import { getTranslation } from '@/services/Translation';

@Component({
  components: { Tab, IconPlus }
})
export default class TabsBar extends Vue {
  @State('list', { namespace: 'tabs' })
  tabs!: Array<TabType>;

  @Mutation('closeTab', { namespace: 'tabs' })
  closeTab!: Function;

  @Mutation('setActiveTab', { namespace: 'tabs' })
  setActiveTab!: Function;

  getTranslation = getTranslation;

  onTabClick(index: number, tab: TabType) {
    if (tab.active) {
      return;
    }
    this.setActiveTab(index);
    if (tab.active && tab.link && this.$route.fullPath !== tab.link) {
      this.$router.push(tab.link);
    }
  }

  onTabDelete(index: number) {
    this.closeTab(index);
    const activeTab = this.tabs.find(tab => tab.active);
    if (activeTab && activeTab.link) {
      this.$router.push(activeTab.link);
    }
  }
}
