// we have to use axios due to CORS policy
import axios, { CancelTokenSource, AxiosRequestConfig, AxiosResponse } from 'axios';
import { getTranslation } from '@/services/Translation';

interface ApiConfig {
  cancelPreviousRequests: boolean;
}

const cacheStorage: { [name: string]: AxiosResponse } = {};

export class ApiService {
  protected endpoint?: string;

  protected params: object = {};

  protected body: object | FormData = {};

  protected token?: string;

  protected cancelPreviousRequests: boolean = false;

  protected cancelTokenSource?: CancelTokenSource;

  protected cacheable: boolean = false;

  public callsCount: number = 0;

  constructor(config?: ApiConfig) {
    if (config) {
      this.cancelPreviousRequests = config.cancelPreviousRequests || false;
    }
  }

  public setEndpoint(endpoint: string) {
    this.endpoint = endpoint;
    return this;
  }

  public setParams(params: object) {
    this.params = params;
    return this;
  }

  public setBody(body: object) {
    this.body = body;
    return this;
  }

  public setToken(token: string) {
    this.token = token;
    return this;
  }

  public cache() {
    this.cacheable = true;
    return this;
  }

  public abort() {
    if (this.cancelTokenSource) {
      this.cancelTokenSource.cancel();
    }
  }

  public async get() {
    return this.send({ method: 'GET', params: this.params });
  }

  public async post() {
    return this.send({
      method: 'POST',
      data: this.body instanceof FormData ? this.body : JSON.stringify(this.body)
    });
  }

  public async patch() {
    return this.send({
      method: 'PATCH',
      data: this.body instanceof FormData ? this.body : JSON.stringify(this.body)
    });
  }

  public async put() {
    return this.send({
      method: 'PUT',
      data: this.body instanceof FormData ? this.body : JSON.stringify(this.body)
    });
  }

  public async delete() {
    return this.send({ method: 'DELETE', params: this.params });
  }

  protected get url() {
    if (this.endpoint) {
      return process.env.VUE_APP_API_URL + this.endpoint;
    }
    return undefined;
  }

  protected get headers() {
    const headers: { [key: string]: string } = {
      'Content-Type': 'application/json'
    };
    if (this.token) {
      headers['Api-Authorization'] = this.token;
    }
    return headers;
  }

  protected async send(config: AxiosRequestConfig) {
    if (this.cancelPreviousRequests && this.cancelTokenSource) {
      // when user quickly clicks on different links in the navigation causing sending several requests in the same time - they could be executed in a random order, so the content could be shown for the latest loaded request (not necessary the last clicked one). To prevent this, we need to cancel previous requests for the same area before sending new ones.
      this.abort();
    }
    this.cancelTokenSource = axios.CancelToken.source();
    this.checkRequestData();
    const url = this.url;
    if (!url) {
      return Promise.reject();
    }
    if (cacheStorage[url]) {
      return Promise.resolve(cacheStorage[url]);
    }
    this.callsCount += 1;
    const response = await axios({
      url,
      headers: this.headers,
      withCredentials: process.env.VUE_APP_API_WITH_CREDENTIALS !== 'false',
      timeout: 30000,
      cancelToken: this.cancelTokenSource.token,
      ...config
    })
      .catch(e => {
        return Promise.reject(e);
      })
      .finally(() => {
        this.callsCount -= 1;
      });
    ApiService.checkResponse(response);
    if (!(response && response.data)) {
      return Promise.reject();
    }
    if (this.cacheable) {
      cacheStorage[url] = response;
    }
    return Promise.resolve(response);
  }

  protected checkRequestData() {
    if (!this.endpoint) {
      throw new Error('Api endpoint is not set');
    }
  }

  protected static checkResponse(response: AxiosResponse | void) {
    if (typeof response !== 'object') {
      throw new Error(getTranslation('defaultErrorMessage'));
    }
    if (typeof response.data !== 'object') {
      throw new Error(`Ошибка соединения. Некорректный ответ от сервера ${typeof response.data}`);
    }
    if (!response.data.success) {
      throw new Error(response.data.message);
    }
  }
}
