















































import Vue from 'vue';
import Component from 'vue-class-component';
import { Prop } from 'vue-property-decorator';
import NavItemLink from '@/components/nav/NavItemLink.vue';
import NavItemFolder from '@/components/nav/NavItemFolder.vue';
import { Author, BookSection, Category, NavigationData } from '@/services/Navigation/types';
import { Getter, Mutation, State } from 'vuex-class';
import UrlBuilderService from '@/services/UrlBuilderService';
import { LABEL_OFFSET_PX, LEVEL_OFFSET_PX } from '@/services/Navigation/constants';

@Component({
  name: 'NavBookSection',
  components: { NavBookSection, NavItemLink, NavItemFolder }
})
export default class NavBookSection extends Vue {
  @Prop({ required: true })
  bookSections!: Array<BookSection>;

  @Prop({ required: true })
  bookSection!: BookSection;

  @Prop({ required: false, default: 0 })
  level!: number;

  @Prop({ required: true })
  showCheckboxes!: boolean;

  @Prop({ required: false })
  category!: Category;

  @Prop({ required: false })
  author!: Author;

  @Prop({ required: false })
  showEntriesCount?: boolean;

  @Prop({ required: false, default: false })
  catalogTree!: boolean;

  @Getter('dataFromStateLanguage', { namespace: 'navigation' })
  navData!: NavigationData;

  @Mutation('toggleBookSectionExpand', { namespace: 'navigation' })
  toggleBookSectionExpand!: Function;

  @Mutation('toggleBookSectionCheck', { namespace: 'navigation' })
  toggleBookSectionCheck!: Function;

  @Mutation('toggleFoundBookSectionCheck', { namespace: 'navigation' })
  toggleFoundBookSectionCheck!: Function;

  @State('language', { namespace: 'navigation' })
  navLanguage!: string;

  @State('showSearchResultsFlag', { namespace: 'navigation' })
  showSearchResultsFlag?: boolean;

  get offset() {
    if (!this.level) {
      return LABEL_OFFSET_PX;
    }
    return this.level * LEVEL_OFFSET_PX + LABEL_OFFSET_PX;
  }

  get children() {
    return this.bookSections.filter(section => section.parentId && section.parentId === this.bookSection.id);
  }

  get url() {
    return UrlBuilderService.getBookSectionUrl({
      language: this.bookSection.book.language,
      categorySlug: this.category ? this.category.slug : '',
      authorSlug: this.author ? this.author.slug : '',
      bookSlug: this.bookSection.book.slug,
      bookSectionSlug: this.bookSection.slug
    });
  }

  get highlight() {
    const { category } = this.$route.params;
    if (this.category && category && this.category.slug !== category) {
      return false;
    }
    return this.bookSection.highlight;
  }

  get hasChildren() {
    return this.children && this.children.length;
  }

  get entriesCount() {
    if (!this.hasChildren) {
      return this.bookSection.doc_count;
    }

    return this.children.reduce((docCount, bookSection) => docCount + (bookSection.doc_count || 0), 0);
  }

  toggleExpand() {
    this.toggleBookSectionExpand({
      bookSectionId: this.bookSection.id,
      bookSlug: this.bookSection.book.slug,
      catalogTree: this.catalogTree
    });
  }

  toggleCheck() {
    if (this.showSearchResultsFlag) {
      this.toggleFoundBookSectionCheck({
        bookSectionId: this.bookSection.id,
        bookSlug: this.bookSection.book.slug
      });
    } else {
      this.toggleBookSectionCheck({
        bookSectionId: this.bookSection.id,
        bookSlug: this.bookSection.book.slug
      });
    }
  }
}
