
















































































import Vue from 'vue';
import Component from 'vue-class-component';
import { Ref, Watch } from 'vue-property-decorator';
import { Getter, State } from 'vuex-class';
import BooksService from '@/services/Api/BooksService';
import Loader from '@/components/ui/Loader.vue';
import BottomBar from '@/components/bottom-bar/BottomBar.vue';
import { BookSection } from '@/services/Navigation/types';
import router from '@/router';
import { Route } from 'vue-router';
import UrlBuilderService from '@/services/UrlBuilderService';
import BookNoteOverlay from '@/components/BookNoteOverlay.vue';
import StringService from '@/services/StringService';
import ContextMenu from '@/components/ContextMenu.vue';
import { getTranslation } from '@/services/Translation';
import UserService from '@/services/Api/UserService';

interface BookSectionWithContent extends BookSection {
  content: {
    book_title: string;
    entities: Array<any>;
    isFirst: boolean;
    title: string;
    is_article: boolean;
  };
}

interface ReadingPosition {
  bookKey: string;
  language: string;
  book: string;
  section: string;
  location: string;
  link: string;
  position: number;
  paragraphAnchor?: string;
}

interface Pagination {
  chapter: number | null;
  poem: number | null;
  section: number | null;
  chapters: Array<any>;
  sections: Array<any>;
  poems: Array<any>;
}

@Component({
  components: { ContextMenu, BookNoteOverlay, BottomBar, Loader }
})
export default class BookContent extends Vue {
  loading: boolean = false;
  loadingMore: boolean = false;
  contentError: boolean = false;
  loadingSectionKey: string | null = null;
  preloadingSectionKeys: Array<string> = [];
  loadingContinuousSection: boolean = false;
  bookSectionsWithContent: { [bookId: number]: Array<BookSectionWithContent> } = {};
  onScrollTimeout?: number;
  readingPositionTimeout?: number;
  viewportResizeTimeout?: number;
  pendingReadingPosition?: ReadingPosition;
  lastReadingPosition?: ReadingPosition;
  lastScrollPosition = 0;
  suppressReaderScrollUntil = 0;
  note = {
    title: '',
    content: '',
    visible: false
  };
  contextMenu = {
    top: 0,
    left: 0,
    link: ''
  };
  getTranslation = getTranslation;

  formatBookTitle(title: string) {
    return title.replace(/\.\s+/g, '.\n');
  }

  @Ref('scroll')
  refScroll!: HTMLDivElement;

  @State('scale', { namespace: 'reader' })
  scale!: number;

  @State('inBookSearch', { namespace: 'search' })
  inBookSearch!: boolean;

  @State('error', { namespace: 'navigation' })
  navigationError!: boolean | Error;

  @Getter('currentBookSection', { namespace: 'navigation' })
  currentBookSection?: BookSection;

  @Getter('currentBookSections', { namespace: 'navigation' })
  currentBookSections?: Array<BookSection>;

  @Getter('pagination', { namespace: 'navigation' })
  pagination?: Pagination;

  async mounted() {
    this.refScroll.addEventListener('scroll', this.onScroll);
    window.addEventListener('resize', this.onViewportResize);
    window.addEventListener('pagehide', this.flushCurrentReadingPosition);
  }

  beforeDestroy() {
    this.refScroll.removeEventListener('scroll', this.onScroll);
    window.removeEventListener('resize', this.onViewportResize);
    window.removeEventListener('pagehide', this.flushCurrentReadingPosition);
    if (this.onScrollTimeout) {
      clearTimeout(this.onScrollTimeout);
    }
    if (this.readingPositionTimeout) {
      clearTimeout(this.readingPositionTimeout);
    }
    if (this.viewportResizeTimeout) {
      clearTimeout(this.viewportResizeTimeout);
    }
    if (this.pendingReadingPosition) {
      this.saveReadingPosition(this.pendingReadingPosition);
    }
  }

  deactivated() {
    if (this.pendingReadingPosition) {
      this.saveReadingPosition(this.pendingReadingPosition);
    }
  }

  updated() {
    this.bindLinksEvent();
  }

  @Watch('$route')
  async onRouteChange(to: Route) {
    if (!['book-section', 'category-book-section', 'author-book-section'].includes(to.name || '')) {
      return;
    }
    this.contentError = false;
    this.$store.commit('navigation/setError', false);
    if (this.isCurrentBookSectionRoute() && this.currentBookSectionWithContent) {
      this.loading = false;
      this.loadingMore = false;
      if (to.query.bookmark === '1' || typeof to.query.anchor === 'string') {
        await this.$nextTick();
        await this.waitForReadingFonts();
        this.scrollToCurrentPage();
      }
      this.updateTabName();
      return;
    }
    if (Object.keys(to.query).find(key => key === 'reading')) {
      this.loadingMore = true;
      try {
        if (await this.fetchContent()) {
          this.updateTabName();
        }
      } catch (e) {
        this.setContentError(e);
      } finally {
        this.loadingMore = false;
      }
      return;
    }
    this.loading = true;
    try {
      if (await this.fetchContent()) {
        await this.$nextTick();
        await this.waitForReadingFonts();
        this.scrollToCurrentPage();
        this.updateTabName();
      }
    } catch (e) {
      this.setContentError(e);
    } finally {
      this.loading = false;
    }
  }

  @Watch('currentBookSection', { immediate: true })
  async onCurrentBookSectionChange(to: BookSection) {
    if (!to) {
      this.loading = true;
      return;
    }

    // Catalog branch commits can briefly clear and restore the selected
    // section. Do not let that transient state re-enable the full-page loader
    // after this section's content has already arrived.
    if (this.currentBookSectionWithContent) {
      this.loading = false;
      this.contentError = false;
      return;
    }

    const sectionKey = `${to.book.id}:${to.id}`;
    if (this.loadingSectionKey !== sectionKey) {
      this.loadingSectionKey = sectionKey;
      try {
        await this.initialLoadContent();
      } finally {
        if (this.loadingSectionKey === sectionKey) {
          this.loadingSectionKey = null;
        }
      }
    }
  }

  isCurrentBookSectionRoute() {
    const currentBookSection = this.currentBookSection;
    if (!currentBookSection) {
      return false;
    }
    return (
      currentBookSection.book.language === this.$route.params.language &&
      currentBookSection.book.slug === this.$route.params.book &&
      currentBookSection.slug === this.$route.params.bookSection
    );
  }

  get currentBookSectionIndex() {
    const currentBookSection = this.currentBookSection;
    const currentBookSections = this.currentBookSections;
    if (!(currentBookSections && currentBookSection)) {
      return null;
    }
    return currentBookSections.findIndex(bookSection => bookSection.id === currentBookSection.id);
  }

  /**
   * Get all sections with content of current book
   */
  get currentBookSectionsWithContent() {
    const currentBookSection = this.currentBookSection;
    if (!currentBookSection) {
      return [];
    }
    const currentBookId = currentBookSection.book.id;
    return this.bookSectionsWithContent[currentBookId] || [];
  }

  /**
   * Get current section with content of current book
   */
  get currentBookSectionWithContent() {
    const currentBookSection = this.currentBookSection;
    if (!currentBookSection) {
      return null;
    }
    return this.currentBookSectionsWithContent
      .filter(one => one)
      .find(bookSection => bookSection.id === currentBookSection.id);
  }

  get tabName() {
    let tabName = '...';
    if (!this.currentBookSectionWithContent) {
      return '';
    }
    if (this.currentBookSectionWithContent.content.is_article) {
      tabName = this.currentBookSectionWithContent.content.book_title;
    } else if (this.currentBookSection) {
      tabName = `${this.currentBookSection.book.name} — ${this.currentBookSection.name}`;
    }
    return tabName;
  }

  get mobilePaginationType() {
    if (!this.pagination) {
      return '';
    }
    if (this.pagination.poem && this.pagination.poems.length > 1) {
      return 'poem';
    }
    if (this.pagination.section && this.pagination.sections.length > 1) {
      return 'section';
    }
    if (this.pagination.chapter && this.pagination.chapters.length > 1) {
      return 'chapter';
    }
    return '';
  }

  get highlight() {
    if (typeof this.$route.query.highlight !== 'string') {
      return '';
    }
    return this.$route.query.highlight.split(',').filter(word => word);
  }

  async initialLoadContent() {
    this.loading = true;
    this.contentError = false;
    try {
      if (!(await this.fetchContent())) {
        return;
      }
      // Keep the content concealed by the loader until its saved scroll
      // position has been applied to the fully rendered section.
      await this.$nextTick();
      await this.waitForReadingFonts();
      this.scrollToCurrentPage();
      this.updateTabName();
    } catch (e) {
      this.setContentError(e);
    } finally {
      this.loading = false;
    }
  }

  setContentError(error: Error) {
    this.contentError = true;
    console.error(error); // eslint-disable-line no-console
  }

  updateTabName() {
    this.$store.commit('tabs/updateActiveTabDetails', {
      name: this.tabName,
      bookName: this.currentBookSection ? this.currentBookSection.book.name : '',
      location: this.currentBookSection ? this.currentBookSection.name : ''
    });
  }

  async fetchContent() {
    if (!this.isCurrentBookSectionRoute()) {
      return false;
    }
    if (!this.currentBookSection) {
      return false;
    }
    const currentBookSection = this.currentBookSection;
    const bookId = currentBookSection.book.id;
    const bookSectionsWithContent = this.currentBookSectionsWithContent.slice(0);

    this.$store.commit('navigation/updatePreloadFlag');
    bookSectionsWithContent[currentBookSection.number] = {
      ...currentBookSection,
      content: await BooksService.getBookSectionContent(
        this.$route.params.language,
        this.$route.params.book,
        currentBookSection.slug
      )
    };

    // To modify keys of object we should use Vue.set in order to support reactivity
    // @see https://vuejs.org/v2/guide/reactivity.html#Change-Detection-Caveats
    Vue.set(this.bookSectionsWithContent, bookId, bookSectionsWithContent);

    // Adjacent sections improve continuous scrolling, but a slow neighbour
    // must never delay the section explicitly requested by the user.
    const adjacentContent = this.preloadAdjacentContent(bookId, currentBookSection.id);
    if (
      this.$route.query.bookmark === '1' ||
      (this.loading && this.getSavedReadingPosition(this.$route.path) > 0)
    ) {
      await adjacentContent;
    }
    return true;
  }

  async preloadAdjacentContent(bookId: number, sectionId: string) {
    const sectionKey = `${bookId}:${sectionId}`;
    if (this.preloadingSectionKeys.includes(sectionKey)) {
      return;
    }
    this.preloadingSectionKeys.push(sectionKey);

    try {
      const [bookSectionsBefore, bookSectionsAfter] = await Promise.all([
        this.fetchContentBeforeCurrent(),
        this.fetchContentAfterCurrent()
      ]);
      const bookSectionsWithContent = (this.bookSectionsWithContent[bookId] || []).slice(0);
      let needFixScroll = false;

      if (bookSectionsBefore) {
        bookSectionsBefore.forEach(bookSection => {
          needFixScroll = needFixScroll || !this.wasBookSectionPreviouslyLoaded(bookSection);
          bookSectionsWithContent[bookSection.number] = bookSection;
        });
      }
      if (bookSectionsAfter) {
        bookSectionsAfter.forEach(bookSection => {
          bookSectionsWithContent[bookSection.number] = bookSection;
        });
      }
      Vue.set(this.bookSectionsWithContent, bookId, bookSectionsWithContent);
      if (needFixScroll) {
        await this.fixScrollPosition();
      }
    } catch (e) {
      console.error(e); // eslint-disable-line no-console
    } finally {
      this.preloadingSectionKeys = this.preloadingSectionKeys.filter(key => key !== sectionKey);
    }
  }

  async doFetchContent(bookSections: Array<BookSection>) {
    return Promise.all(
      bookSections.map(async bookSection => ({
        ...bookSection,
        content: await BooksService.getBookSectionContent(
          this.$route.params.language,
          this.$route.params.book,
          bookSection.slug
        )
      }))
    );
  }

  getParagraphAnchor(bookSection: BookSection, index: number) {
    const section = String(bookSection.slug || bookSection.id || 'section')
      .toLowerCase()
      .replace(/[^a-z0-9]+/g, '-')
      .replace(/^-|-$/g, '');
    return `paragraph-${section || 'section'}-${index}`;
  }

  async loadNextContinuousSection() {
    if (
      this.loadingContinuousSection ||
      !this.currentBookSection ||
      !this.currentBookSections ||
      !this.currentBookSections.length
    ) {
      return;
    }
    const bookId = this.currentBookSection.book.id;
    const loaded = (this.bookSectionsWithContent[bookId] || []).slice(0);
    const loadedIds = new Set(loaded.filter(Boolean).map(section => section.id));
    const lastLoadedIndex = this.currentBookSections.reduce(
      (lastIndex, section, index) => (loadedIds.has(section.id) ? index : lastIndex),
      -1
    );
    const nextSection = this.currentBookSections
      .slice(lastLoadedIndex + 1)
      .find(section => !loadedIds.has(section.id));
    if (!nextSection) {
      return;
    }
    this.loadingContinuousSection = true;
    try {
      const [content] = await this.doFetchContent([nextSection]);
      loaded[nextSection.number] = content;
      Vue.set(this.bookSectionsWithContent, bookId, loaded);
    } catch (e) {
      console.error(e); // eslint-disable-line no-console
    } finally {
      this.loadingContinuousSection = false;
    }
  }

  async fetchContentBeforeCurrent() {
    if (!this.currentBookSections) {
      return;
    }
    const bookSectionsBefore = [];
    const index = this.currentBookSectionIndex;
    if (index !== null) {
      for (let i = index; i >= 0; i--) {
        const bookSection = this.currentBookSections[i];
        if (i === index) {
          continue;
        }
        if (bookSection.preload) {
          bookSectionsBefore.push(bookSection);
        } else {
          break;
        }
      }
      return this.doFetchContent(bookSectionsBefore.reverse());
    }
  }

  async fetchContentAfterCurrent() {
    if (!this.currentBookSections) {
      return;
    }
    const bookSectionsAfter = [];
    const index = this.currentBookSectionIndex;
    if (index !== null) {
      for (let i = index; i < this.currentBookSections.length; i++) {
        const bookSection = this.currentBookSections[i];
        if (i === index) {
          continue;
        }
        if (bookSection.preload) {
          bookSectionsAfter.push(bookSection);
        } else {
          break;
        }
      }
      return this.doFetchContent(bookSectionsAfter);
    }
  }

  async fixScrollPosition() {
    if (!this.currentBookSection) {
      return;
    }
    await this.$nextTick();
    if (!this.currentBookSection) {
      return;
    }
    const bookSectionLink = this.getBookSectionUrl(this.currentBookSection);
    const currentBookSectionElement = this.findPageElement(bookSectionLink);
    if (currentBookSectionElement) {
      this.scrollToPage(
        currentBookSectionElement,
        this.getSavedReadingPosition(currentBookSectionElement.dataset.page || '')
      );
    }
  }

  onScroll() {
    const currentScrollPosition = this.refScroll.scrollTop;
    const remaining = this.refScroll.scrollHeight - this.refScroll.clientHeight - currentScrollPosition;
    if (
      remaining <= this.refScroll.clientHeight * 1.5 &&
      typeof this.loadNextContinuousSection === 'function'
    ) {
      this.loadNextContinuousSection();
    }
    const delta = currentScrollPosition - this.lastScrollPosition;
    if (Math.abs(delta) > 12 && Date.now() >= this.suppressReaderScrollUntil) {
      const event = {
        direction: delta > 0 ? 'down' : 'up',
        delta: Math.abs(delta),
        top: currentScrollPosition,
        max: Math.max(0, this.refScroll.scrollHeight - this.refScroll.clientHeight)
      };
      this.$emit('reader-scroll', event);
      this.$root.$emit('reader-scroll', event);
      this.lastScrollPosition = currentScrollPosition;
    } else if (Math.abs(delta) > 0) {
      this.lastScrollPosition = currentScrollPosition;
    }
    if (this.onScrollTimeout) {
      clearTimeout(this.onScrollTimeout);
    }
    this.onScrollTimeout = setTimeout(() => {
      const scrollPosition = this.refScroll.scrollTop;
      const pages: Array<HTMLElement> = Array.from(this.refScroll.querySelectorAll('[data-page]'));
      const newPage = pages.find(el => el.offsetTop + el.offsetHeight - 20 > scrollPosition);
      const readingPosition = this.getReadingPosition(newPage);

      if (readingPosition) {
        this.updateReadingPositionLocally(readingPosition);
        this.scheduleReadingPositionSave(readingPosition);
      }

      // todo maybe bad solution: once content is loaded is should be put before scroll
      if (
        newPage &&
        newPage.dataset.page &&
        (!newPage.dataset.isParent || scrollPosition === 0) &&
        (router.currentRoute.path !== newPage.dataset.page || !router.currentRoute.query.reading)
      ) {
        router.replace({ path: newPage.dataset.page, query: { ...router.currentRoute.query, reading: '1' } });
      }
    }, 50);
  }

  onClickOnNote(e: Event) {
    const target = e.target as HTMLDivElement;
    const element = target && (target.classList.contains('footnote') ? target : target.closest('.footnote'));
    if (element) {
      const note = element.getAttribute('data-footnote-content');
      const number = element.getAttribute('data-footnote-number');
      this.note.title = number ? `${getTranslation('note')} №${number}` : '';
      this.note.content = note || '';
      this.note.visible = true;
    }
  }

  resetNote() {
    this.note.title = '';
    this.note.content = '';
    this.note.visible = false;
  }

  scrollToCurrentPage() {
    const pageElement = this.findPageElement(this.$route.path);
    if (pageElement) {
      const queryAnchor = typeof this.$route.query.anchor === 'string' ? this.$route.query.anchor : '';
      const savedAnchor = this.getSavedParagraphAnchor(this.$route.path);
      const anchor = queryAnchor || savedAnchor;
      if (anchor && this.scrollToParagraph(anchor)) {
        const readingPosition = this.getReadingPosition(pageElement);
        if (readingPosition) {
          this.updateReadingPositionLocally(readingPosition);
          this.scheduleReadingPositionSave(readingPosition);
        }
      } else {
        this.scrollToPage(pageElement, this.getSavedReadingPosition(this.$route.path));
      }
      this.clearBookmarkOpeningFlag();
    }
  }

  clearBookmarkOpeningFlag() {
    if (this.$route.query.bookmark !== '1' && !this.$route.query.anchor) {
      return;
    }
    const query = { ...this.$route.query };
    delete query.bookmark;
    delete query.anchor;
    router.replace({ path: this.$route.path, query }).catch(() => {});
  }

  async waitForReadingFonts() {
    const fonts = (document as any).fonts;
    if (fonts && fonts.ready) {
      try {
        await fonts.ready;
      } catch (e) {
        // A failed optional webfont must not prevent the book from opening.
      }
    }
    await this.$nextTick();
  }

  scrollToPage(el: HTMLElement, position: number = 0) {
    this.suppressReaderScrollUntil = Date.now() + 150;
    this.refScroll.scrollTop = el.offsetTop + el.offsetHeight * Math.max(0, Math.min(1, position));
    this.lastScrollPosition = this.refScroll.scrollTop;
    const readingPosition = this.getReadingPosition(el);
    if (readingPosition) {
      this.updateReadingPositionLocally(readingPosition);
      this.scheduleReadingPositionSave(readingPosition);
    }
  }

  getSavedReadingPosition(link: string) {
    const activeTab = this.$store.state.tabs.list.find((tab: { active: boolean }) => tab.active);
    if (!(activeTab && activeTab.link && activeTab.link.split('?')[0] === link)) {
      return 0;
    }
    return typeof activeTab.position === 'number' ? activeTab.position : 0;
  }

  getSavedParagraphAnchor(link: string) {
    const activeTab = this.$store.state.tabs.list.find((tab: { active: boolean }) => tab.active);
    if (!(activeTab && activeTab.link && activeTab.link.split('?')[0] === link)) {
      return '';
    }
    return activeTab.paragraphAnchor || '';
  }

  scrollToParagraph(anchor: string) {
    const paragraph = Array.from(this.refScroll.querySelectorAll('[data-paragraph-anchor]')).find(
      element => (element as HTMLElement).dataset.paragraphAnchor === anchor
    ) as HTMLElement | undefined;
    if (!paragraph) {
      return false;
    }
    const scrollRect = this.refScroll.getBoundingClientRect();
    const paragraphRect = paragraph.getBoundingClientRect();
    this.suppressReaderScrollUntil = Date.now() + 150;
    this.refScroll.scrollTop += paragraphRect.top - scrollRect.top - 16;
    this.lastScrollPosition = this.refScroll.scrollTop;
    return true;
  }

  getReadingPosition(page?: HTMLElement) {
    if (!(page && page.dataset.page)) {
      return null;
    }
    const section = this.currentBookSectionsWithContent
      .filter(one => one)
      .find(bookSection => this.getBookSectionUrl(bookSection) === page.dataset.page);
    if (!section) {
      return null;
    }
    const relativeTop = Math.max(0, this.refScroll.scrollTop - page.offsetTop);
    const position = page.offsetHeight ? Math.min(1, relativeTop / page.offsetHeight) : 0;
    const canMeasureParagraphs =
      typeof this.refScroll.getBoundingClientRect === 'function' &&
      typeof page.querySelectorAll === 'function';
    const scrollRect = canMeasureParagraphs ? this.refScroll.getBoundingClientRect() : null;
    const paragraphs: Array<HTMLElement> = canMeasureParagraphs
      ? Array.from(page.querySelectorAll('[data-paragraph-anchor]'))
      : [];
    const paragraph =
      paragraphs
        .filter(
          element =>
            !!scrollRect &&
            typeof element.getBoundingClientRect === 'function' &&
            element.getBoundingClientRect().top <= scrollRect.top + 32
        )
        .pop() || paragraphs[0];
    return {
      bookKey: `${section.book.language}:${section.book.slug}`,
      language: section.book.language,
      book: section.book.slug,
      section: section.slug,
      location: section.name,
      link: page.dataset.page,
      position,
      paragraphAnchor: paragraph ? paragraph.dataset.paragraphAnchor || '' : ''
    } as ReadingPosition;
  }

  updateReadingPositionLocally(position: ReadingPosition) {
    this.lastReadingPosition = position;
    this.$store.commit('tabs/updateBookTabDetails', {
      bookKey: position.bookKey,
      details: {
        link: position.link,
        location: position.location,
        position: position.position,
        paragraphAnchor: position.paragraphAnchor,
        updatedAt: new Date().toISOString()
      }
    });
  }

  scheduleReadingPositionSave(position: ReadingPosition) {
    this.pendingReadingPosition = position;
    if (this.readingPositionTimeout) {
      clearTimeout(this.readingPositionTimeout);
    }
    this.readingPositionTimeout = setTimeout(() => {
      this.readingPositionTimeout = undefined;
      if (this.pendingReadingPosition) {
        this.saveReadingPosition(this.pendingReadingPosition);
      }
    }, 700);
  }

  flushCurrentReadingPosition() {
    if (this.onScrollTimeout) {
      clearTimeout(this.onScrollTimeout);
      this.onScrollTimeout = undefined;
    }
    const pages: Array<HTMLElement> = Array.from(this.refScroll.querySelectorAll('[data-page]'));
    const page = pages.find(item => item.offsetTop + item.offsetHeight - 20 > this.refScroll.scrollTop);
    // During pagehide the browser may already be reflowing an orientation
    // change. Prefer the last position measured while layout was stable.
    const position = this.pendingReadingPosition || this.lastReadingPosition || this.getReadingPosition(page);
    if (!position) {
      return;
    }
    this.updateReadingPositionLocally(position);
    this.pendingReadingPosition = undefined;
    UserService.saveReadingPositionOnPageHide({
      language: position.language,
      book: position.book,
      section: position.section,
      position: position.position,
      section_positions: this.getSavedSectionPositions(position.bookKey)
    });
  }

  onViewportResize() {
    const position = this.lastReadingPosition;
    if (!position) {
      return;
    }
    if (this.viewportResizeTimeout) {
      clearTimeout(this.viewportResizeTimeout);
    }
    this.viewportResizeTimeout = setTimeout(() => {
      this.viewportResizeTimeout = undefined;
      const page = this.findPageElement(position.link);
      if (page) {
        this.scrollToPage(page, position.position);
      }
    }, 120);
  }

  async saveReadingPosition(position: ReadingPosition) {
    this.pendingReadingPosition = undefined;
    try {
      const saved = await UserService.saveReadingPosition({
        language: position.language,
        book: position.book,
        section: position.section,
        position: position.position,
        section_positions: this.getSavedSectionPositions(position.bookKey)
      });
      this.$store.commit('tabs/updateBookTabDetails', {
        bookKey: position.bookKey,
        details: {
          updatedAt: saved.updated_at || new Date().toISOString()
        }
      });
    } catch (e) {
      // The local reading position remains available if synchronization is temporarily unavailable.
    }
  }

  getSavedSectionPositions(bookKey: string) {
    const tab = this.$store.state.tabs.list.find((item: { bookKey?: string }) => item.bookKey === bookKey);
    return tab && tab.sectionPositions ? { ...tab.sectionPositions } : {};
  }

  findPageElement(url: string) {
    return this.refScroll.querySelector(`[data-page="${url}"]`) as HTMLElement | null;
  }

  wasBookSectionPreviouslyLoaded(bookSection: BookSectionWithContent) {
    const currentBookSection = this.currentBookSection;
    if (!currentBookSection) {
      return false;
    }
    return !!this.currentBookSectionsWithContent
      .filter(one => one)
      .find(one => one.id === bookSection.id && one.book.id === bookSection.book.id);
  }

  getAuthorUrl(slug: string) {
    return UrlBuilderService.getAuthorUrl({
      language: this.$route.params.language,
      authorSlug: slug
    });
  }

  getBookSectionUrl(bookSection: BookSection | BookSectionWithContent) {
    return UrlBuilderService.getBookSectionUrl({
      language: bookSection.book.language,
      categorySlug: this.$route.params.category,
      authorSlug: this.$route.params.author,
      bookSlug: bookSection.book.slug,
      bookSectionSlug: bookSection.slug
    });
  }

  getContent(entity: { content: string; type?: string }) {
    let content =
      entity.type === 'word-by-word' ? this.decorateWordByWordTerms(entity.content) : entity.content;
    if (this.highlight && this.highlight.length) {
      for (const word of this.highlight) {
        content = StringService.replaceAll(content, word, `<em class="highlight">${word}</em>`);
      }
    }
    return content;
  }

  decorateWordByWordTerms(content: string) {
    const template = document.createElement('template');
    template.innerHTML = content;
    Array.from(template.content.querySelectorAll('em, i, strong, b, span')).forEach(element => {
      const nextSibling = element.nextSibling;
      const separator = nextSibling && nextSibling.textContent ? nextSibling.textContent : '';
      if (
        !element.classList.contains('word-by-word-term') &&
        !element.closest('.word-by-word-term') &&
        /^\s*[—–-]\s+/.test(separator)
      ) {
        element.classList.add('word-by-word-term');
      }
    });
    const walker = document.createTreeWalker(template.content, NodeFilter.SHOW_TEXT);
    const textNodes: Array<Text> = [];
    let currentNode = walker.nextNode();
    while (currentNode) {
      textNodes.push(currentNode as Text);
      currentNode = walker.nextNode();
    }

    textNodes.forEach(textNode => {
      const parent = textNode.parentElement;
      if (parent && parent.closest('em, i, .word-by-word-term')) {
        return;
      }
      const text = textNode.textContent || '';
      const termPattern = /(^|;\s*)([^;—–]+?)(\s+[—–]\s+)/g;
      const fragment = document.createDocumentFragment();
      let lastIndex = 0;
      let match = termPattern.exec(text);
      if (!match) {
        return;
      }
      do {
        fragment.appendChild(document.createTextNode(text.slice(lastIndex, match.index) + match[1]));
        const term = document.createElement('span');
        term.className = 'word-by-word-term';
        term.textContent = match[2];
        fragment.appendChild(term);
        fragment.appendChild(document.createTextNode(match[3]));
        lastIndex = termPattern.lastIndex;
        match = termPattern.exec(text);
      } while (match);
      fragment.appendChild(document.createTextNode(text.slice(lastIndex)));
      textNode.replaceWith(fragment);
    });

    return template.innerHTML;
  }

  captureCurrentReadingPosition() {
    if (this.onScrollTimeout) {
      clearTimeout(this.onScrollTimeout);
      this.onScrollTimeout = undefined;
    }
    const pages: Array<HTMLElement> = Array.from(this.refScroll.querySelectorAll('[data-page]'));
    const page = pages.find(item => item.offsetTop + item.offsetHeight - 20 > this.refScroll.scrollTop);
    const position = this.getReadingPosition(page);
    if (position) {
      this.updateReadingPositionLocally(position);
      this.lastReadingPosition = position;
    }
    return position;
  }

  bindLinksEvent() {
    const links = this.refScroll.querySelectorAll('a.link-to-poem:not([data-bound="1"])') as NodeListOf<
      HTMLAnchorElement
    >;
    if (!links.length) {
      return;
    }

    const scrollOffsetTop = this.refScroll.getBoundingClientRect().top;

    for (const link of links) {
      link.addEventListener('click', e => {
        e.preventDefault();
        this.contextMenu.link = link.getAttribute('href') || '';
        this.contextMenu.top = this.refScroll.scrollTop + e.pageY - scrollOffsetTop;
        this.contextMenu.left = link.offsetLeft;
      });
      link.dataset.bound = '1';
    }
  }
}
