










































































































import Vue from 'vue';
import Component from 'vue-class-component';
import { Prop, Watch } from 'vue-property-decorator';
import InfoIcon from '@/assets/icons/info.svg';
import GlobeIcon from '@/assets/icons/globe.svg';
import BookCoverIcon from '@/assets/icons/book-cover.svg';
import BottomBarControl from '@/components/bottom-bar/BottomBarControl.vue';
import { Book, BookSection, PagingItem } from '@/services/Navigation/types';
import { Getter, Mutation, State } from 'vuex-class';
import UrlBuilderService from '@/services/UrlBuilderService';
import BottomBarRelated from '@/components/bottom-bar/BottomBarRelated.vue';
import { getTranslation } from '@/services/Translation';
import BottomBarTooltip from '@/components/bottom-bar/BottomBarTooltip.vue';
import BottomBarBookInfo from '@/components/bottom-bar/BottomBarBookInfo.vue';

interface Pagination {
  chapter: number | null;
  poem: number | null;
  section: number | null;
  chapters: Array<any>;
  sections: Array<any>;
  poems: Array<any>;
}

@Component({
  components: {
    BottomBarBookInfo,
    BottomBarTooltip,
    BottomBarRelated,
    BottomBarControl,
    InfoIcon,
    GlobeIcon,
    BookCoverIcon
  }
})
export default class BottomBar extends Vue {
  book: Book | null = null;

  showRelatedBooks = false;

  showBookInfo = false;

  getTranslation = getTranslation;

  @Prop({ required: true })
  bookContent!: any;

  @Prop({ default: '' })
  mobilePaginationType!: string;

  @State('scale', { namespace: 'reader' })
  scale!: number;

  @Getter('currentBookSection', { namespace: 'navigation' })
  currentSection?: BookSection;

  @Getter('pagination', { namespace: 'navigation' })
  pagination!: Pagination;

  @Mutation('setScale', { namespace: 'reader' })
  setScale!: Function;

  @Watch('$route')
  onRouteChange() {
    this.showRelatedBooks = false;
  }

  getEntityIndex(list: Array<PagingItem>, number: number) {
    return list.findIndex(one => one.number === number);
  }

  getPrevUrl(list: Array<PagingItem>, number: number) {
    const index = this.getEntityIndex(list, number);
    const pagingItem = list[index - 1];
    if (!pagingItem) {
      return null;
    }
    return UrlBuilderService.getBookSectionUrl({
      language: this.$route.params.language,
      categorySlug: this.$route.params.category,
      bookSlug: this.$route.params.book,
      bookSectionSlug: pagingItem.bookSectionSlug
    });
  }

  getNextUrl(list: Array<PagingItem>, number: number) {
    const index = this.getEntityIndex(list, number);
    const pagingItem = list[index + 1];
    if (!pagingItem) {
      return null;
    }
    return UrlBuilderService.getBookSectionUrl({
      language: this.$route.params.language,
      categorySlug: this.$route.params.category,
      bookSlug: this.$route.params.book,
      bookSectionSlug: pagingItem.bookSectionSlug
    });
  }

  get prevChapterUrl() {
    return this.pagination.chapter
      ? this.getPrevUrl(this.pagination.chapters, this.pagination.chapter)
      : null;
  }

  get nextChapterUrl() {
    return this.pagination.chapter
      ? this.getNextUrl(this.pagination.chapters, this.pagination.chapter)
      : null;
  }

  get prevSectionUrl() {
    return this.pagination.section
      ? this.getPrevUrl(this.pagination.sections, this.pagination.section)
      : null;
  }

  get nextSectionUrl() {
    return this.pagination.section
      ? this.getNextUrl(this.pagination.sections, this.pagination.section)
      : null;
  }

  get prevPoemUrl() {
    return this.pagination.poem ? this.getPrevUrl(this.pagination.poems, this.pagination.poem) : null;
  }

  get nextPoemUrl() {
    return this.pagination.poem ? this.getNextUrl(this.pagination.poems, this.pagination.poem) : null;
  }

  get bookUrl() {
    return UrlBuilderService.getBookUrl({
      language: this.$route.params.language,
      categorySlug: this.$route.params.category,
      bookSlug: this.$route.params.book
    });
  }

  getTranslationUrl(code: string) {
    if (!this.currentSection) {
      return '';
    }
    const { number_code_chapter, number_code_poem, number_code_section } = this.currentSection;

    if (number_code_chapter || number_code_poem || number_code_section) {
      return UrlBuilderService.getBookSectionUrl({
        language: code,
        categorySlug: this.$route.params.category,
        bookSlug: this.$route.params.book,
        bookSectionSlug: this.$route.params.bookSection
      });
    }
    return UrlBuilderService.getBookUrl({
      language: code,
      categorySlug: this.$route.params.category,
      bookSlug: this.$route.params.book
    });
  }
}
