import Vue from 'vue';
import Router, { Route } from 'vue-router';
import { store } from './store';
import Home from './views/content/Home.vue';
import Login from './views/Login.vue';
import ForgotPassword from './views/ForgotPassword.vue';
import ResetPassword from './views/ResetPassword.vue';
import Registration from './views/Registration.vue';
import VerifyEmail from '@/views/VerifyEmail.vue';
import Help from '@/views/content/Help.vue';
import Reader from '@/views/Reader.vue';
import BookContent from '@/views/content/BookContent.vue';
import BookCover from '@/views/content/BookCover.vue';
import UserService from '@/services/Api/UserService';
import AuthorBio from '@/views/content/AuthorBio.vue';
import SearchResults from '@/views/content/SearchResults.vue';

Vue.use(Router);

let entryUrl: string | null = null;

const guard = async (to: Route, from: Route, next: Function) => {
  let needEmailVerification = false;

  store.commit('startLoading');
  const user = await UserService.getUser().catch(async e => {
    if (!e.response) {
      return null;
    }
    if (e.response.status === 401) {
      await store.dispatch('auth/logout');
    }
    if (e.response.status === 403) {
      needEmailVerification = true;
    }
    return null;
  });
  store.commit('stopLoading');

  if (needEmailVerification) {
    entryUrl = to.fullPath;
    return next('/user/email/resend');
  }

  if (!user) {
    entryUrl = to.fullPath;
    return next('/login');
  }

  if (!store.state.auth.authorized) {
    store.commit('auth/login', '');
  }
  store.commit('user/set', user);
  store.commit('tabs/switchOwner', String(user.id || user.email));
  store.commit('bookmarks/switchOwner', String(user.id || user.email));

  if (entryUrl) {
    const url = entryUrl;
    entryUrl = null;
    return next(url);
  }
  return next();
};

export default new Router({
  mode: 'history',
  base: process.env.BASE_URL,
  routes: [
    {
      path: '/login',
      name: 'login',
      component: Login
    },
    {
      path: '/forgot-password',
      name: 'forgot-password',
      component: ForgotPassword
    },
    {
      path: '/password/reset',
      name: 'reset-password',
      component: ResetPassword
    },
    {
      path: '/password/reset/:token',
      name: 'reset-password-token',
      component: ResetPassword
    },
    {
      path: '/registration',
      name: 'registration',
      component: Registration
    },
    {
      path: '/user/email/verify/:userId/:hash',
      name: 'verify-email',
      component: VerifyEmail
    },
    {
      path: '/user/email/resend',
      name: 'verify-email-resend',
      component: VerifyEmail
    },
    {
      path: '/',
      component: Reader,
      children: [
        {
          path: '/',
          component: Home
        },
        {
          path: '/:language/library',
          name: 'mobile-library',
          component: Home
        },
        {
          path: '/:language/tabs',
          redirect: to => `/${to.params.language}/bookmarks`
        },
        {
          path: '/:language/bookmarks',
          name: 'mobile-bookmarks',
          component: Home
        },
        {
          path: '/:language/settings',
          name: 'mobile-settings',
          component: Home
        },
        {
          path: '/help',
          component: Help
        },
        {
          path: '/:language/books/:book',
          name: 'book',
          component: BookCover
        },
        {
          path: '/:language/books/:book/:bookSection',
          name: 'book-section',
          component: BookContent
        },
        {
          path: '/:language/categories/:category/:book',
          name: 'category-book',
          component: BookCover
        },
        {
          path: '/:language/categories/:category/:book/:bookSection',
          name: 'category-book-section',
          component: BookContent
        },
        {
          path: '/:language/authors/:author',
          name: 'author-bio',
          component: AuthorBio
        },
        {
          path: '/:language/authors/:author/:book',
          name: 'author-book',
          component: BookCover
        },
        {
          path: '/:language/authors/:author/:book/:bookSection',
          name: 'author-book-section',
          component: BookContent
        },
        {
          path: '/:language/search',
          name: 'search-results',
          component: SearchResults
        }
      ],
      beforeEnter: guard
    }
  ]
});
