

























import Vue from 'vue';
import Component from 'vue-class-component';
import router from '@/router';
import UrlBuilderService from '@/services/UrlBuilderService';
import { Prop, Watch } from 'vue-property-decorator';
import { LANGUAGE_CODE_ENGLISH, LANGUAGE_CODE_RUSSIAN } from '@/constants';
import BooksWithTranslations from '@/components/BooksWithTranslations.vue';
import { getTranslation } from '@/services/Translation';

interface BookSection {
  book_slug: string;
  slug: string;
  books: Array<{ name: string; slug: string; translations: Array<{ short_name: string; code: string }> }>;
  content: Array<any>;
  patch: Array<{ title: string }>;
}

@Component({
  components: { BooksWithTranslations }
})
export default class SearchPriorityBookSection extends Vue {
  contentLanguage = LANGUAGE_CODE_RUSSIAN;

  contentLanguageButtonText = {
    [LANGUAGE_CODE_RUSSIAN]: getTranslation('showOnEnglishLanguage'),
    [LANGUAGE_CODE_ENGLISH]: getTranslation('showOnRussianLanguage')
  };

  getTranslation = getTranslation;

  @Prop({ required: true })
  bookSection!: BookSection;

  get bookSectionUrl() {
    return UrlBuilderService.getBookSectionUrl({
      language: router.currentRoute.params.language,
      bookSlug: this.bookSection.book_slug,
      bookSectionSlug: this.bookSection.slug
    });
  }

  get bookSectionTitle() {
    return this.bookSection.patch.map(({ title }) => title).join(' • ');
  }

  get bookTranslations() {
    return this.bookSection.books.map(book => ({
      ...book,
      translations: book.translations.map(translation => ({
        ...translation,
        url: UrlBuilderService.getBookSectionUrl({
          language: translation.code,
          bookSlug: book.slug,
          bookSectionSlug: this.bookSection.slug
        })
      }))
    }));
  }

  get contentOfSelectedLanguage() {
    return this.bookSection.content.find(one => one.language === this.contentLanguage);
  }

  @Watch('interfaceLanguage')
  async onChangeInterfaceLang() {
    this.contentLanguageButtonText = {
      [LANGUAGE_CODE_RUSSIAN]: getTranslation('showOnRussianLanguage'),
      [LANGUAGE_CODE_ENGLISH]: getTranslation('showOnEnglishLanguage')
    };
  }

  switchContentLanguage() {
    if (this.contentLanguage === LANGUAGE_CODE_RUSSIAN) {
      this.contentLanguage = LANGUAGE_CODE_ENGLISH;
    } else {
      this.contentLanguage = LANGUAGE_CODE_RUSSIAN;
    }
  }
}
