import { ActionTree, Module, MutationTree } from 'vuex';
import CookieService from '@/services/CookieService';
import AuthService from '@/services/Api/AuthService';
import { RootState } from '@/store';

export interface AuthState {
  token: string;
  authorized: boolean;
}

function syncInitialToken(): AuthState {
  const token = CookieService.get('api_token') || '';
  return token ? { token, authorized: true } : { token: '', authorized: false };
}

const state: AuthState = syncInitialToken();

const actions: ActionTree<AuthState, RootState> = {
  async login({ commit }, { email, password }) {
    const response = await AuthService.login(email, password);
    commit('login', response.headers['api-token']);
    commit('user/set', response.data.data, { root: true });
    commit('tabs/switchOwner', String(response.data.data.id || response.data.data.email), { root: true });
    commit('bookmarks/switchOwner', String(response.data.data.id || response.data.data.email), {
      root: true
    });
  },
  logout({ commit }) {
    commit('startLoading', null, { root: true });
    // @toDo: uncomment when api implement this method
    // await AuthService.logout();
    // store.dispatch('unsetUser');
    commit('logout');
    commit('tabs/switchOwner', 'guest', { root: true });
    commit('bookmarks/switchOwner', 'guest', { root: true });
    commit('user/unset', null, { root: true });
    commit('stopLoading', null, { root: true });
  }
};

const mutations: MutationTree<AuthState> = {
  login(state: AuthState, token: string) {
    state.token = token;
    state.authorized = true;
    if (token) {
      CookieService.set('api_token', token);
    }
  },
  logout(state: AuthState) {
    state.token = '';
    state.authorized = false;
    CookieService.remove('api_token');
  }
};

export const module = {
  namespaced: true,
  state,
  actions,
  mutations
} as Module<AuthState, RootState>;
