import { store } from '@/store';
import { ApiService } from '@/services/Api/ApiService';
import { endpoints } from '@/api-endpoints.json';
import { LANGUAGE_CODE_DEFAULT } from '@/constants';

export default class BooksService {
  private static instance: BooksService;

  private apiService: ApiService = new ApiService();

  private static getInstance() {
    if (!BooksService.instance) {
      BooksService.instance = new BooksService();
    }
    return BooksService.instance;
  }

  static async getNewBooks() {
    const endpoint = endpoints.books.newBooks;
    const instance = this.getInstance();
    return instance.apiService
      .setEndpoint(endpoint)
      .setParams({
        language: store.state.reader.interfaceLanguage || LANGUAGE_CODE_DEFAULT
      })
      .setToken(store.state.auth.token)
      .get()
      .then(response => response.data.data);
  }

  static async getBookCover(lang: string, book: string) {
    const instance = this.getInstance();
    return instance.apiService
      .setEndpoint(endpoints.books.cover.replace(':lang', lang).replace(':book', book))
      .setToken(store.state.auth.token)
      .cache()
      .get()
      .then(response => response.data.data);
  }

  static async getBookSectionContent(lang: string, book: string, section: string) {
    const instance = this.getInstance();
    return instance.apiService
      .setEndpoint(
        endpoints.books.content
          .replace(':lang', lang)
          .replace(':book', book)
          .replace(':section', section)
      )
      .setToken(store.state.auth.token)
      .cache()
      .get()
      .then(response => response.data.data);
  }
}
